contract InvMutTest {
    C c;
    uint256 observedDuringTransfer;
    bool observed;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 depositAmount, uint256 am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);
        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;
        uint256 b0 = c.balances(address(this)); if (__ESBMC_reverted()) return;
        require(b0 >= 1 ether);
        require(am > 0 && am <= b0);
        observed = false;
        bool reverted;
        c.Collect(am); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint256 b1 = c.balances(address(this)); if (__ESBMC_reverted()) return;
        assert(!reverted && observed && observedDuringTransfer == b0 - am && b1 == b0 - am);
    }

    receive() external payable {
        observedDuringTransfer = c.balances(address(this));
        observed = true;
    }
}

