pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;
    uint256 observedDuringTransfer;
    bool observed;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 depositAmount, uint256 am) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        try c.Deposit{value: depositAmount}() {} catch { return; }
        uint256 b0;
        try c.balances(address(this)) returns (uint256 __r) { b0 = __r; } catch { return; }
        vm.assume(b0 >= 1 ether);
        vm.assume(am > 0 && am <= b0);
        observed = false;
        bool reverted;
        try c.Collect(am) { reverted = false; } catch { reverted = true; }
        uint256 b1;
        try c.balances(address(this)) returns (uint256 __r) { b1 = __r; } catch { return; }
        assertTrue(!reverted && observed && observedDuringTransfer == b0 - am && b1 == b0 - am);
    }

    function testFuzz_run(uint256 depositAmount, uint256 am) public {
        _run(depositAmount, am);
    }

    receive() external payable {
        observedDuringTransfer = c.balances(address(this));
        observed = true;
    }
}
